  db = new Database(':memory:')
  clock = Date.parse('2026-09-28T10:00:00.000Z')
  ids = 0
  store = createConnectionStore({
    db,
    cipher: createFieldCipher('store-test-secret', () => {}),
    now: () => new Date((clock += 1000)).toISOString(),
    newId: () => `conn-${++ids}`,
  })
})

